  (21270, 0, 'zhCN', '我好像把赞达拉狂妄者衬肩弄丢了，你能帮助我吗？', ''),
  (21270, 1, 'zhCN', '我好像把赞达拉狂妄者护腕弄丢了，你能帮助我吗？', ''),
  (21270, 2, 'zhCN', '我好像把赞达拉狂妄者外套弄丢了，你能帮助我吗？', ''),
  (21270, 3, 'zhCN', '我好像把赞达拉暗影大师坠饰弄丢了，你能帮助我吗？', ''),
  (21270, 4, 'zhCN', '我好像把赞达拉暗影坠饰弄丢了，你能帮助我吗？', ''),
