  (21271, 0, 'zhCN', '我好像把赞达拉捕猎者腰带弄丢了，你能帮助我吗？', ''),
  (21271, 1, 'zhCN', '我好像把赞达拉捕猎者护腕弄丢了，你能帮助我吗？', ''),
  (21271, 2, 'zhCN', '我好像把赞达拉捕猎者衬肩弄丢了，你能帮助我吗？', ''),
  (21271, 3, 'zhCN', '我好像把漩涡之怒弄丢了，你能帮助我吗？', ''),
  (21271, 4, 'zhCN', '我好像把漩涡之藤弄丢了，你能帮助我吗？', ''),
  (21271, 5, 'zhCN', '我好像把漩涡之藤弄丢了，你能帮助我吗？', ''),
  (21271, 6, 'zhCN', '我好像把漩涡之藤弄丢了，你能帮助我吗？', ''),
  (21272, 0, 'zhCN', '真高兴可以看到暗影议会失败后燃烧之刃可以重新扛起大旗。', ''),
  (21273, 0, 'zhCN', '也就是说燃烧之刃只是挡子弹的吗？', ''),
  (21274, 0, 'zhCN', '如果你需要我的话……', ''),
  (21276, 0, 'zhCN', '你怎么知道？我是说……是的，我正在寻找那块碎片，它在你这里吗？', ''),
  (21277, 0, 'zhCN', '好的。哪里？', ''),
  (21278, 0, 'zhCN', '铜须的……胡须啊！你在说什么！', ''),
  (21279, 0, 'zhCN', '鱼？你给了个什么？你说拯救艾泽拉斯所有生命的关键是一条鱼？', ''),
  (21280, 0, 'zhCN', '一条小鱼？大海里全都是小鱼！有一百万的好几次方条小鱼！', ''),
  (21281, 0, 'zhCN', '请继续吧。', ''),
  (21282, 0, 'zhCN', '你把一块鱼放在这里和东部王国之间的海域？这块鱼有这种特殊能力？', ''),
  (21283, 0, 'zhCN', '你疯了。', ''),
  (21284, 0, 'zhCN', '我在认真地听呢。', ''),
  (21285, 0, 'zhCN', '请再说一次。', ''),
  (21286, 0, 'zhCN', '好吧，我们直说吧。你把权杖放在了你在用阿纳克洛斯飞行时你自己创造的小鱼身上，现在你希望我制造一个……奥金鱼漂或者其它什么……用来抓住你那躲起来的小鱼？并且这可能招致一个元素领主的愤怒？我说错什么细节吗？也许我需要在一次日食，在闰年，并且不穿衣服的情况下去做这件事情？', ''),
  (21287, 0, 'zhCN', '太棒了！还有，敢问，我如何获得一个奥金鱼漂？', ''),
  (21288, 0, 'zhCN', '但是…', ''),
  (21289, 0, 'zhCN', '我相信你。', ''),
  (21290, 0, 'zhCN', '我需要答案，食人魔！', ''),
  (21291, 1, 'zhCN', '为什么巨石之拳离这这么远？你知道那是怪物的领土。', ''),
  (21292, 2, 'zhCN', '你认为你想吃什么就吃什么吗？很显然你正在尝试吃破碎的东西。', ''),
  (21293, 3, 'zhCN', '北部，希尔盖？', ''),
  (21295, 0, 'zhCN', '我已经杀了很多你说的食人魔，兰特瑞索。我并不害怕。', ''),
  (21310, 0, 'zhCN', '我想占用你一点时间，先生。', ''),
  (21311, 0, 'zhCN', '为什么呢，当然。我有一些事情需要在阁楼中向您汇报，安维尔德先生！', ''),
  (21312, 0, 'zhCN', '你好，伊崔格。我从黑石塔带来了些消息。', ''),
  (21313, 0, 'zhCN', '只有一个大酋长，伊崔格！', ''),
  (21314, 0, 'zhCN', '你是什么意思？', ''),
  (21315, 0, 'zhCN', '壁炉谷？但是……', ''),
  (21316, 0, 'zhCN', '我会接受这个任务，伊崔格。', ''),
  (21317, 0, 'zhCN', '啊，这就是他们怎么把黑铁感到塔底的。', ''),
  (21318, 0, 'zhCN', '没准这里有条路？', ''),
  (21319, 0, 'zhCN', '随你的便吧，伊崔格。', ''),
  (21321, 0, 'zhCN', '魂能是什么?', 'NULL'),
  (21322, 0, 'zhCN', '抱歉，我没想到你能听懂我说的话。你在这里做什么？', ''),
  (21323, 0, 'zhCN', '是吗？也许你该告诉我是什么让你烦恼的。', ''),
  (21324, 0, 'zhCN', '什么约定？', ''),
  (21325, 0, 'zhCN', '他是怎么破坏约定的？', ''),
  (21326, 0, 'zhCN', '也许我能提供一些帮助。我们来做个交易吧，萨特。我会杀了那头巨兽并带回未铸造的胸甲。作为交换，你要教我如何制造这个胸甲。', ''),
  (21330, 0, 'zhCN', '我可没有犯错。', ''),
  (21331, 0, 'zhCN', '你像是迷失了自己，奈法利安。我听不懂你在说什么。', ''),
  (21332, 0, 'zhCN', '那就试试看吧。', ''),
  (21333, 0, 'zhCN', '我无法战胜瓦拉斯塔兹，不过我可以辅助治疗你们。', ''),
  (21334, 0, 'zhCN', '瓦拉斯塔兹，不！！', ''),
  (21335, 0, 'zhCN', '我们已经准备好与你并肩作战了，阿卡玛。', ''),
  (21400, 0, 'zhCN', '我需要一个塞纳里奥的灯笼。', ''),
  (21400, 1, 'zhCN', '那是什么植物？对费伍德森林有那么大的污染？', ''),
  (21402, 0, 'zhCN', '我下定决心了。让我遗忘炼金专精吧！', 'NULL'),
  (21403, 0, 'zhCN', '我下定决心了。让我遗忘炼金专精吧！', 'NULL'),
