  (2422, 0, 'zhCN', '你觉得达丹加怎么样？', ''),
  (2465, 0, 'zhCN', '吉安娜女士，这听起来像是个奇怪的请求……但是我正在照顾一个非常害羞的孩子。对他来说，你是个英雄，他想要你的签名。', 'NULL'),
  (2562, 1, 'zhCN', '古博，我不知道怎么钓鱼。', 'NULL'),
