  (2884, 0, 'zhCN', '什么职责？', 'NULL'),
  (2885, 0, 'zhCN', '是梦境吗？', 'NULL'),
  (2886, 0, 'zhCN', '我祈求能得到这样的经历。', 'NULL'),
  (2887, 0, 'zhCN', '这样的赞扬我可承受不起，高图斯。', 'NULL'),
  (2888, 0, 'zhCN', '长官！我将不惜一切代价来完成任务！', 'NULL'),
  (2889, 0, 'zhCN', '是，长官！谢谢你，长官！', 'NULL'),
  (2890, 1, 'zhCN', '绑定炉石。', ''),
  (2890, 5, 'zhCN', '我想从你这儿买东西。。', ''),
  (2901, 0, 'zhCN', '你好伊崔格，我从黑石塔带来了一些消息。', ''),
  (2902, 0, 'zhCN', '只有一个大酋长，伊崔格！', ''),
  (2903, 0, 'zhCN', '你是什么意思？', ''),
  (2904, 0, 'zhCN', '壁炉谷？ 但是……', ''),
  (2905, 0, 'zhCN', '我接受你的建议，伊崔格。', ''),
  (2906, 0, 'zhCN', '啊，他们就是这样把黑铁推到塔下的。', ''),
  (2907, 0, 'zhCN', '也许存在一条出去的路？', ''),
  (2908, 0, 'zhCN', '如你所愿，伊崔格。', ''),
  (2951, 0, 'zhCN', '你究竟是怎么进去的？', 'NULL'),
  (2952, 0, 'zhCN', '我想从你这儿买东西。。', ''),
  (2984, 0, 'zhCN', '告诉我关于那块皮的事情。', 'NULL'),
  (2985, 0, 'zhCN', '关于磨损的憎恶缝合线的章节。', 'NULL'),
  (2985, 1, 'zhCN', '关于魔化红线的章节。', 'NULL'),
  (2985, 2, 'zhCN', '关于莱斯·霜语的防腐液的章节。', 'NULL'),
  (2985, 3, 'zhCN', '关于奥术水晶和奥金的章节。', 'NULL'),
  (2985, 4, 'zhCN', '关于暗影之皮的章节。', 'NULL'),
  (2991, 0, 'zhCN', '我如何才能获得比斯巨兽的皮呢？', 'NULL'),
  (2992, 0, 'zhCN', '假设我已经得到了比斯巨兽的皮，那么你还需要什么东西吗？你能用它做些什么？', 'NULL'),
  (2993, 0, 'zhCN', '好！', 'NULL'),
  (2994, 0, 'zhCN', '我将洗耳恭听。', 'NULL'),
  (2995, 0, 'zhCN', '让我搞搞清楚。你穿着这件……这件熔岩服，在火红的岩浆里面游泳，不，仰泳？而且在毫无察觉的情况下，被这只野兽吞下了肚？', 'NULL'),
  (2996, 0, 'zhCN', '我必须知道一些事情：你如何穿着这个东西解决个人问题的？', 'NULL'),
  (2997, 0, 'zhCN', '哦？', 'NULL'),
  (2998, 0, 'zhCN', '下次再遇到这种事情的时候我会好好考虑一下的。', 'NULL'),
  (2999, 0, 'zhCN', '我想，你应该去玛雷弗斯那里。', 'NULL'),
  (30005, 0, 'zhCN', '我弄丢了幽灵眼镜。', ''),
  (30005, 1, 'zhCN', '我弄丢了幽灵眼镜。', ''),
  (30008, 1, 'zhCN', '我弄丢了库卡隆信号枪。', ''),
  (30200, 0, 'zhCN', '我需要另一副瑟银镣铐。', ''),
  (30201, 0, 'zhCN', '你能切换伦鲁迪洛尔吗？', ''),
  (30201, 1, 'zhCN', '你能切换罗克迪洛尔吗？', ''),
  (30211, 0, 'zhCN', '让我看看我能飞到哪里。', ''),
  (30211, 1, 'zhCN', '我要飞往暮冬要塞。', ''),
  (30212, 0, 'zhCN', '眼睛指引我来到这儿，艾瑞斯。', ''),
  (30213, 0, 'zhCN', '我很适合看这个？', ''),
  (30214, 0, 'zhCN', '我不知道该怎么想，艾瑞斯。如果有什么需要帮助的话我会用我的力量帮助你。', ''),
  (30215, 0, 'zhCN', '这么多天过去了，艾瑞斯。', ''),
  (30216, 0, 'zhCN', '所以我怎么帮你？', ''),
  (30228, 0, 'zhCN', '我弄丢了瓦塔拉克饰品的左半边。', ''),
  (30228, 1, 'zhCN', '我弄丢了瓦塔拉克饰品的上半边。', ''),
  (30228, 2, 'zhCN', '我弄丢了瓦塔拉克饰品的右半边。', ''),
  (30230, 0, 'zhCN', '准备好了, 欧鲁诺克。让我们击败森卢肯，解放元素！', ''),
  (30231, 0, 'zhCN', '我与你同在，托里姆。', ''),
  (30232, 0, 'zhCN', '给了我个炸弹！', ''),
  (30233, 0, 'zhCN', '大领主，我做好准备了！', ''),
  (3044, 0, 'zhCN', '或许我能帮上忙。萨特，我们来谈笔交易吧。我去取回这块未铸造的胸甲并杀死野兽古拉鲁克。作为交换，你要教我如何制造胸甲。', 'NULL'),
  (3045, 0, 'zhCN', '他是怎么破坏协议的？', 'NULL'),
  (3046, 0, 'zhCN', '什么交易？', 'NULL'),
  (3047, 0, 'zhCN', '是吗？或许你该告诉我是什么让你烦恼。', 'NULL'),
  (3048, 0, 'zhCN', '很抱歉，我没有意识到你可以理解我说的话。你在这儿做什么？', 'NULL'),
  (3049, 0, 'zhCN', '你必须原谅我，罗拉克斯，我并没有说“疯狂”。', ''),
