  (3664, 0, 'zhCN', '战争之王，请将你的智慧与我共享。', 'NULL'),
  (3665, 0, 'zhCN', '有什么发现？', 'NULL'),
  (3666, 0, 'zhCN', '篡位者？', 'NULL'),
  (3667, 0, 'zhCN', '恕我直言，统帅大人--为什么不消灭他们？难道这不会巩固我们的地位吗？', 'NULL'),
