  (5277, 1, 'zhCN', '另一个武器大师能教些什么？', ''),
  (5346, 0, 'zhCN', '请告诉我关于雷姆洛斯和扎尔塔的历史。', 'NULL'),
  (5349, 0, 'zhCN', '告诉我关于玛拉顿的更多信息。', 'NULL'),
  (5349, 1, 'zhCN', '告诉我关于扎尔塔的更多信息。', 'NULL'),
  (5349, 2, 'zhCN', '请告诉我关于雷姆洛斯和扎尔塔的历史。', 'NULL'),
  (5351, 0, 'zhCN', '我不太明白……', 'NULL'),
  (5352, 0, 'zhCN', '不，真的，我还是不懂……', 'NULL'),
  (5382, 0, 'zhCN', '训练我', ''),
  (54000, 0, 'zhCN', '掀起霜豹的尾巴来看看它是公的还是母的。', ''),
  (5461, 0, 'zhCN', '我想要建立工会。', ''),
  (5461, 1, 'zhCN', '我如何完成工会表格？', ''),
  (5481, 0, 'zhCN', '罗卡鲁，我丢了龙火护符。你能再给我一个吗？', 'NULL'),
  (5482, 0, 'zhCN', '哈尔琳，我把龙火护符弄丢了。你能帮我再做一个吗？', 'NULL'),
  (5483, 0, 'zhCN', '巴尼尔，看起来我好像丢失了章节I。', ''),
  (5483, 1, 'zhCN', '巴尼尔，看起来我好像丢失了章节II。', ''),
  (5483, 2, 'zhCN', '巴尼尔，看起来我好像丢失了章节III。', ''),
  (5483, 3, 'zhCN', '巴尼尔，看起来我好像丢失了章节IV。', ''),
  (55000, 0, 'zhCN', '掀起冰爪熊的尾巴来看看它是公的还是母的。', ''),
  (55002, 1, 'zhCN', '我愿意为温妮小姐拔出我的佩剑。', ''),
  (5502, 0, 'zhCN', '莱恩，我把达图尔的变形魔棒弄丢了。', 'NULL'),
  (56000, 0, 'zhCN', '恐惧魔王？你是说魔王贝恩霍勒。他向你问好，并有消息给你……', ''),
  (56001, 0, 'zhCN', '不，乌拉泰克。他知道你的秘密。他知道你跟克索诺斯的赫尔努拉斯之间的阴谋。', ''),
  (56002, 0, 'zhCN', '叛徒，我可没骗你。魔王贝恩霍勒想要你的命。', ''),
  (5602, 0, 'zhCN', '谢谢你，埃隆巴克。我们等你开门。', ''),
  (561, 0, 'zhCN', '什么是“地下矩阵”？', ''),
  (562, 0, 'zhCN', '土灵是什么？', ''),
  (563, 0, 'zhCN', '你所说的异常是指什么？', ''),
  (5630, 0, 'zhCN', '拉瑞安，我想帮助你打败这些家伙！', 'NULL'),
  (564, 0, 'zhCN', '什么是“基础弹性建设”？', ''),
  (565, 0, 'zhCN', '因此……土灵是从石头中诞生的？', ''),
  (566, 0, 'zhCN', '关于土灵还有什么我应该知道的？', ''),
  (5665, 0, 'zhCN', '训练我', ''),
  (5667, 0, 'zhCN', '你好诺特，我是裁缝。你能教我如何制作戈多克食人魔装吗？', ''),
  (5667, 1, 'zhCN', '你好诺特，我是制皮师。你能教我如何制作戈多克食人魔装吗？', ''),
  (5667, 2, 'zhCN', '我发现了镣铐钥匙……', ''),
  (5667, 3, 'zhCN', '为什么让我修复陷阱？为什么不用以前的方法除掉卫兵呢？！', ''),
  (5668, 0, 'zhCN', '我猜是的！', ''),
  (567, 0, 'zhCN', '我想现在我明白了造物者设计土灵的意图了。你之前说到的土地异常是什么情况？', ''),
  (5675, 0, 'zhCN', '你怎么看？', ''),
  (568, 0, 'zhCN', '什么！？高压力环境会导致大地破碎。', ''),
  (5687, 0, 'zhCN', '战斗？', ''),
  (5688, 0, 'zhCN', '请继续。', ''),
  (5689, 0, 'zhCN', '我在听，德米提恩。', ''),
  (569, 0, 'zhCN', '当大地破碎时发生了什么？', ''),
  (570, 0, 'zhCN', '穴居人？！你提到的穴居人和现在世界上的一个种族是同一个吗？', ''),
  (57000, 0, 'zhCN', '你的职责是什么？', 'NULL'),
  (57001, 0, 'zhCN', '什么是奥丹姆圆盘？', 'NULL'),
  (57002, 0, 'zhCN', '奥丹姆圆盘在哪里？', 'NULL'),
  (57003, 0, 'zhCN', '什么？我们的世界“被安排了新的探访计划”？这是什么意思？！', 'NULL'),
  (57004, 0, 'zhCN', '那么……奥丹姆里面到底有些什么？', 'NULL'),
  (57005, 0, 'zhCN', '我找到奥丹姆圆盘之后会回来的。', 'NULL'),
  (57006, 0, 'zhCN', '我把瓦塔拉克公爵的饰品弄丢了！', 'NULL'),
  (57006, 1, 'zhCN', '我把一块瓦塔拉克公爵的饰品碎片弄丢了！', 'NULL'),
  (57006, 2, 'zhCN', '我把召唤火盆弄丢了！', 'NULL'),
  (57006, 3, 'zhCN', '伯德雷，告诉我发生了什么事。', 'NULL'),
  (57007, 0, 'zhCN', '你在告诉我有关迷雾之刃的事情，以及你们怎样错误地接手了这个任务。', 'NULL'),
  (57008, 0, 'zhCN', '不，不，请继续……这里的空气……似乎，呃，有点浑浊……', 'NULL'),
  (57009, 0, 'zhCN', '请继续，伯德雷。', 'NULL'),
  (5701, 0, 'zhCN', '不知情被抓的？怎么回事？', ''),
  (57010, 0, 'zhCN', '完了？', 'NULL'),
  (57011, 0, 'zhCN', '你所属的雇佣兵团迷雾之刃到底怎么了？', 'NULL'),
  (57015, 0, 'zhCN', '是的，我检查过了，上面的那一瓣找不到了！', 'NULL'),
  (57015, 1, 'zhCN', '是的，我检查过了，左边这一瓣找不到了！', 'NULL'),
  (57018, 0, 'zhCN', '是的，请把它召唤回来！', 'NULL'),
  (5702, 0, 'zhCN', '<点头>', ''),
  (57023, 0, 'zhCN', '纳特，我想要购买一些臭泥鱼诱饵！', 'NULL'),
  (57023, 1, 'zhCN', '我要怎么样才能捕捉到鱼饵所需的臭泥鱼？', 'NULL'),
  (5703, 0, 'zhCN', '<递过逐风者的禁锢之颅>', ''),
  (5704, 0, 'zhCN', '所以接下来拉格纳罗斯做了什么？', ''),
  (5708, 0, 'zhCN', '我是新国王？你们在讨论什么？', ''),
  (5708, 1, 'zhCN', '心腹？致哀？', ''),
  (5709, 0, 'zhCN', '游戏？你疯了吗？', 'NULL'),
  (571, 0, 'zhCN', '当土灵不稳定时，你提到的两个结果。第二个是什么？', ''),
  (5710, 0, 'zhCN', '为什么你这么渺小……', ''),
  (5711, 0, 'zhCN', '记住我的话，小鬼。我会抓住你！', ''),
  (5712, 0, 'zhCN', '死吧！', ''),
  (5713, 0, 'zhCN', '准备好见你的造物主吧。', ''),
  (5715, 0, 'zhCN', '成为了新国王是不是美滋滋！现在，让我们回想一下你以前都说了什么……', ''),
  (572, 0, 'zhCN', '矮人！！你是说矮人是由土灵进化来的？', ''),
  (5721, 0, 'zhCN', '你什么意思，买？！我现在可是国王……成为国王可真是太好了！', ''),
  (5721, 1, 'zhCN', '让我看看你卖什么，克雷格？', ''),
  (5723, 0, 'zhCN', '一个悲伤的传说。谢谢你，精灵。', ''),
  (5724, 0, 'zhCN', '我们活在一个充满无尽悲剧的世界。', ''),
  (5725, 0, 'zhCN', '我要杀一些东西，是吗？', ''),
  (5726, 0, 'zhCN', '真令人着迷啊，请继续。', ''),
  (5727, 0, 'zhCN', '请继续。', ''),
  (5728, 0, 'zhCN', '我对上层精灵了解很少，对辛德拉更是一无所知。', ''),
  (5729, 0, 'zhCN', '这儿发生了什么？先知！', ''),
  (573, 0, 'zhCN', '这些矮人会有一天是相同的，对吗？矮人和土灵还保持着其它联系吗？', ''),
  (5733, 0, 'zhCN', '是啊，你真聪明。你觉得自己有多聪明呢，斯里基克？', ''),
  (5734, 0, 'zhCN', '那么，现在我是国王了……你们要供奉我什么？！', ''),
  (5735, 0, 'zhCN', '喊我“老大”。你们要供奉给我什么？！', ''),
  (5738, 0, 'zhCN', '额……我就是这样找到他们的。我要告诉国王他们是个威胁！船长说……我曾经听说卫兵芬古斯曾叫你大胖子，无用的矮子情人！', ''),
  (5739, 0, 'zhCN', '嗯，我要在国王惩罚我以前带一些在外面发现的囚犯。', ''),
  (574, 0, 'zhCN', '谁是创造者？', ''),
  (5740, 0, 'zhCN', '好吧……给我看看贡品！', ''),
  (5743, 0, 'zhCN', '为巨大的损失表示哀悼。', ''),
  (5743, 1, 'zhCN', '为巨大的损失表示哀悼。', ''),
  (5747, 0, 'zhCN', '（继续。）', 'NULL'),
  (5749, 0, 'zhCN', '<将原理图抄写到工程笔记本中。>', ''),
  (575, 0, 'zhCN', '这已经足够去思考了。', ''),
  (5750, 0, 'zhCN', '将我传送到熔火之心，洛索斯。', ''),
  (576, 0, 'zhCN', '我会立刻使用光碟。', ''),
  (5762, 0, 'zhCN', '雷克斯洛特，我把瑟银镣铐弄丢了。', 'NULL'),
  (5764, 0, 'zhCN', '拉比恩，你为什么说这是个巧合？', 'NULL'),
  (5765, 0, 'zhCN', '丰饶之果？', 'NULL'),
  (5766, 0, 'zhCN', '但是，有些事情好像出了差错，是吗？', 'NULL'),
  (5767, 0, 'zhCN', '如果丰饶之果——或者说是魔藤——完全堕落，那会发生什么事呢？', 'NULL'),
  (5768, 0, 'zhCN', '下次再遇到这种事情的时候我会好好考虑一下的。', 'NULL'),
  (5779, 0, 'zhCN', '要做什么？', ''),
  (5780, 0, 'zhCN', '火焰领主和胆敢阻拦的人都会被我的愤怒所摧残。', ''),
  (5781, 0, 'zhCN', '我要为辟地打扫出来一片地方。那是什么？', ''),
  (5783, 0, 'zhCN', '给我一艘船，大领主。', ''),
  (581, 0, 'zhCN', '训练我', ''),
  (5812, 0, 'zhCN', '你是能制造出源质的塑地者吗？', 'NULL'),
  (5813, 0, 'zhCN', '弗兰扎尔，你对此了解多少？', 'NULL'),
  (5814, 0, 'zhCN', '裂缝？', 'NULL'),
  (5815, 0, 'zhCN', '发生了什么事？', 'NULL'),
  (5818, 0, 'zhCN', '我想买点东西。', ''),
  (5842, 0, 'zhCN', '我要干些什么呢？', 'NULL'),
  (5843, 0, 'zhCN', '这很有趣，但是你到底想说什么？', 'NULL'),
  (5844, 0, 'zhCN', '什么任务？', 'NULL'),
  (5845, 0, 'zhCN', '我在寻找一名强大的术士。', 'NULL'),
  (5848, 1, 'zhCN', '我需要一个新的兽人孤儿哨。', ''),
  (5849, 1, 'zhCN', '我需要一个新的人类孤儿哨。', ''),
  (5851, 0, 'zhCN', '血蹄酋长，也许这请求听起来有些奇怪……但是我正在照顾一个非常害羞的孩子。对他来说，你就是个英雄，是他请求我来拿到你的蹄印。', 'NULL'),
  (5853, 0, 'zhCN', '训练我', ''),
  (5854, 0, 'zhCN', '训练我', ''),
  (5855, 0, 'zhCN', '训练我', ''),
  (5856, 0, 'zhCN', '训练我', ''),
  (5864, 0, 'zhCN', '我想从你这儿买点东西。', 'NULL'),
  (5868, 0, 'zhCN', '我可不会受你的魅惑。去死吧。', 'NULL'),
  (5870, 0, 'zhCN', '这么说你是疯狂的克林弗兰？真不幸，我所期望的是一次真正的挑战。你敢以真面目视人吗？', 'NULL'),
  (5871, 0, 'zhCN', '我知道你是摧毁者阿托留斯。恶魔，现身吧！', 'NULL'),
  (5872, 0, 'zhCN', '侏儒？真可怜。面对我吧，恶魔！', 'NULL'),
  (590, 0, 'zhCN', '你可以指给我方向吗？', ''),
  (592, 0, 'zhCN', '你可以指给我方向吗？', ''),
  (593, 0, 'zhCN', '训练我', ''),
  (593, 1, 'zhCN', '告诉我更多关于铸造护甲的事情。', ''),
  (593, 2, 'zhCN', '告诉我更多关于铸造武器的事情。', ''),
  (59563, 0, 'zhCN', '约翰，我有公务在身。我需要一切有关温德索尔元帅的信息。你最后一次见他是什么时候？', 'NULL'),
  (59563, 1, 'zhCN', '挤“奶”吧，约翰。', 'NULL'),
  (59564, 0, 'zhCN', '你干了些什么？', 'NULL'),
  (59565, 0, 'zhCN', '矮人，脑子放清醒点。我可没问你什么老爹啊名誉啊之类的事儿。', 'NULL'),
  (59566, 0, 'zhCN', '反对者？', 'NULL'),
  (59567, 0, 'zhCN', '真有趣……继续。', 'NULL'),
  (59568, 0, 'zhCN', '温德索尔就那样死了……', 'NULL'),
  (59569, 0, 'zhCN', '他是怎么死的？', 'NULL'),
  (59570, 0, 'zhCN', '好吧，他到底在哪儿？等一会！你喝醉了吗？', 'NULL'),
  (59571, 0, 'zhCN', '他为什么在黑石深渊？', 'NULL'),
  (59572, 0, 'zhCN', '300？那么说黑铁矮人杀死了他，并把他拖到了深渊里？', 'NULL'),
  (59573, 0, 'zhCN', '啊……反对者。', 'NULL'),
  (59574, 0, 'zhCN', '谢谢你，约翰。你的故事振奋人心，使我受益匪浅。', 'NULL'),
  (5962, 0, 'zhCN', '我要看看你的物品。', ''),
  (5967, 0, 'zhCN', '我需要坐骑。', ''),
  (597, 0, 'zhCN', '训练我', ''),
  (597, 1, 'zhCN', '我想要遗忘护甲锻造！', ''),
  (6001, 0, 'zhCN', '<把手放在球上。>', ''),
  (60041, 0, 'zhCN', '（继续。）', 'NULL'),
  (60042, 0, 'zhCN', '（继续。）', 'NULL'),
  (60043, 0, 'zhCN', '（继续。）', 'NULL'),
  (6021, 0, 'zhCN', '我做不到，瓦拉斯塔兹！一定有什么办法可以拯救你！', 'NULL'),
  (6023, 0, 'zhCN', '我需要坐骑。', ''),
  (6059, 0, 'zhCN', '把旅店设为我的家。', ''),
  (6059, 1, 'zhCN', '让我看看你的货物。', ''),
  (6086, 0, 'zhCN', '我要从你那儿买东西。', ''),
  (6087, 0, 'zhCN', '我要从你那儿买东西。', ''),
  (6087, 1, 'zhCN', '你能教给我什么？', ''),
  (6101, 0, 'zhCN', '瓦拉斯塔兹，不！！！', 'NULL'),
  (6141, 0, 'zhCN', '我现在赢得了在战歌峡谷中购买哪些物品的权利？', 'NULL'),
  (6142, 0, 'zhCN', '我现在赢得了在战歌峡谷中购买哪些物品的权利？', 'NULL'),
  (6162, 0, 'zhCN', '我需要坐骑。', ''),
  (6182, 0, 'zhCN', '为什么你的东西都这么实惠？你还有利润吗？', ''),
  (6185, 0, 'zhCN', '正如我的君主所期望的那样，我当场就杀了那个人，因为他不过是一个小偷和骗子！', ''),
  (6185, 1, 'zhCN', '我把那人交给了我的君主惩处，因为他违反了这儿的法律，我有责任惩处他。', ''),
  (6185, 2, 'zhCN', '我没收了他偷来的玉米，警告他“偷窃是走向末日和毁灭的必经之路”，但是我让他回家了。', ''),
  (6185, 3, 'zhCN', '我允许他带了些足够他养几日家的玉米，鼓励了他几句，就让他离开了。', ''),
  (6186, 0, 'zhCN', '我已经准备好去寻找我的命运了！', ''),
  (6187, 0, 'zhCN', '我按照君主的指示处死了他，并且让他在临死前饱受折磨地死去，作为他对我的人民所犯罪行的惩处。', ''),
  (6187, 1, 'zhCN', '我按照王上的命令处决他，但是我尽可能地让他少受痛苦。正义必须得到伸张，但我们也要心怀怜悯。', 'NULL'),
  (6187, 2, 'zhCN', '我愿意以自己生命的代价来拯救他，然后他就可以证明自己的清白。如果可以的话，我会不惜一切代价来帮助他。', 'NULL'),
  (6202, 0, 'zhCN', '让我看看你的货物。', ''),
  (6202, 1, 'zhCN', '告诉我更多关于暗月卡牌的事情。', ''),
  (6207, 0, 'zhCN', '告诉我更多关于野兽套卡的事情。', ''),
  (6207, 1, 'zhCN', '告诉我更多关于入口套卡的事情。', ''),
  (6207, 2, 'zhCN', '告诉我更多关于元素套卡的事情。', ''),
  (6207, 3, 'zhCN', '告诉我更多关于督军套卡的事情。', ''),
  (6207, 4, 'zhCN', '告诉我更多关于愤怒套卡的事情。', ''),
  (6207, 5, 'zhCN', '告诉我更多关于月光套卡的事情。', ''),
  (6207, 6, 'zhCN', '告诉我更多关于祝福套卡的事情。', ''),
  (6207, 7, 'zhCN', '告诉我更多关于风暴套卡的事情。', ''),
  (6207, 8, 'zhCN', '还有其他的套卡存在吗？', ''),
  (6208, 0, 'zhCN', '我挑战他的邪恶与蛮横，不惜一切代价捍卫王上的荣耀。', 'NULL'),
  (6208, 1, 'zhCN', '我平静但略有表示地对这种冒犯一言不发，让他对自己犯下的错心怀恐惧。回去之后，我会把这一切禀报王上。', 'NULL'),
  (6208, 2, 'zhCN', '我默不作声，忽略了这种侮辱。我不会告诉我的王上，因为我将不惜一切代价保护和平。这只是一次侮辱——而不是一次完全的宣战。', 'NULL'),
  (6209, 0, 'zhCN', '我会反对我的兄弟加入军队，即使我们的关系会因此产生永久的裂痕。对他自己和周围的人来说，他无疑是个危险，要想指望他会逐渐进步可就太冒险了。', 'NULL'),
  (6209, 1, 'zhCN', '我会支持我的兄弟加入军队，虽然这或许会威胁到军队的安全。我和军队的其他成员会帮助他，我相信他能够适应这儿的生活并且学会生存之道。', 'NULL'),
  (6209, 2, 'zhCN', '我会想办法让他不参加危险的任务，完全不需要他做任何事情，以此来保存我的家族的血脉。', 'NULL'),
  (6210, 0, 'zhCN', '我会把野兽的耳朵给我的长官看，并把击杀野兽归功于我，我自己花赏金。把别人的所作所为当做自己的行为是无耻的。', ''),
  (6210, 1, 'zhCN', '我会把野兽的耳朵给我的长官看，并声称是我自己杀死了野兽——毕竟，确实是我杀了它。然后我会把赏金给那些穷困潦倒的骑士补贴家用。', ''),
  (6210, 2, 'zhCN', '我将对这次击杀缄口不言，并且那些骑士必须向我保证要补贴家用。', ''),
  (6211, 0, 'zhCN', '我很乐意去追寻那些你提及的已定命运！我已经准备好了！', ''),
  (6213, 1, 'zhCN', '你说暗月马戏团已经到了？它在哪儿？', ''),
  (6214, 0, 'zhCN', '当暗月马戏团到来时，他们会在哪里扎营？', ''),
  (6230, 0, 'zhCN', '让我看看你的饮料。', ''),
  (6231, 0, 'zhCN', '你的意思是告诉我你卖青蛙？', ''),
  (6233, 0, 'zhCN', '你有什么可出售的？', ''),
  (6234, 0, 'zhCN', '嗯……食物。', ''),
