  (6540, 2, 'zhCN', '碧蓝圣殿骑士！我手中握着你的召唤纹章。响应我的召唤吧！', 'NULL'),
  (6540, 3, 'zhCN', '土色圣殿骑士！我手中握着你的召唤纹章。响应我的召唤吧！', 'NULL'),
  (6540, 4, 'zhCN', '苍白圣殿骑士！我手中握着你的召唤纹章。响应我的召唤吧！', 'NULL'),
  (6542, 0, 'zhCN', '卑鄙的公爵，听好了！我可不是暮光之锤的走狗！我是来向你提出挑战的！来吧，受死吧……', 'NULL'),
