  (7524, 1, 'zhCN', '训练我', ''),
  (7531, 0, 'zhCN', '我是一名囚犯，它看起来像什么？在我离开太阳之门后，德莱尼就抓住了我。他们杀死了传送门控制者，摧毁了大门。太阳王对发生的这一切非常不满。', ''),
  (7533, 0, 'zhCN', '我信了，你也相信我。你的信息对我很有用，血精灵。你帮助了我们很多。', ''),
  (7534, 0, 'zhCN', '矢量感应器非常巨大。我希望我们能有更多的畸变者去看守其它几个弱点。', ''),
  (7535, 0, 'zhCN', '希隆娜丝是一名艾瑞达人……是的……我是说……很明显……', ''),
  (7536, 0, 'zhCN', '难以置信。希隆娜丝是怎么完成的？', ''),
  (7537, 0, 'zhCN', '啊，对，希隆娜丝。我都快忘了希隆娜丝在这儿了。我在外域服侍希隆娜丝。不过我还没听说这么可憎的事情，当我在这世界还不是完全体的时候，可恶的德莱尼就抓住我了。', ''),
