  (7668, 0, 'zhCN', '向西走。', ''),
  (7668, 1, 'zhCN', '向东走。', ''),
  (7675, 0, 'zhCN', '我已经杀了很多你说的食人魔，兰特瑞索。我并不害怕。', ''),
  (7676, 0, 'zhCN', '我需要做什么？', ''),
  (7677, 0, 'zhCN', '那我们只能抗争到底，兰特瑞索。我不会眼睁睁地看着你掠夺我们的城镇，杀害我们的人民。', ''),
  (7678, 0, 'zhCN', '我们希望你能将石拳兽人后撤，离开我的领地。相应地，我们也会将部队撤回来。', ''),
  (7679, 0, 'zhCN', '很抱歉，我无意冒犯。我为我的人民而来。', ''),
  (7680, 0, 'zhCN', '我听说过你这一族，但从未想到能亲眼见到混血龙类。', ''),
  (7681, 0, 'zhCN', '另一半呢？', ''),
  (7682, 0, 'zhCN', '我应该知道吗？对我来说你看起来像一个兽人。', ''),
  (7690, 0, 'zhCN', '训练我', ''),
  (7691, 0, 'zhCN', '训练我', ''),
  (7692, 0, 'zhCN', '忒洛斯，我知道你肯定藏着这个秘密，告诉我吧。', ''),
  (7704, 0, 'zhCN', '埃博尔，你得告诉我是怎么回事，我得知道！', ''),
  (7704, 1, 'zhCN', '把你知道的再跟我讲一遍！', 'NULL'),
  (7712, 0, 'zhCN', '我想要浏览你的货物。', ''),
  (7713, 0, 'zhCN', '让我看看你的货物。', ''),
  (7715, 0, 'zhCN', '熔炉营地？', ''),
  (7716, 0, 'zhCN', '你现在怎么看他们？', ''),
  (7717, 0, 'zhCN', '现在呢？', ''),
  (7718, 0, 'zhCN', '军团？', ''),
  (7719, 0, 'zhCN', '我看到扭曲的钢铁，嗅到了分裂的大地。', ''),
  (7719, 1, 'zhCN', '告诉我更多关于在卡拉波废墟训练场的恶魔猎人的事情。', ''),
  (7722, 1, 'zhCN', '我要兑换印记！', ''),
  (7722, 2, 'zhCN', '把旗子给我！', ''),
  (7724, 1, 'zhCN', '我要兑换印记！', ''),
  (7724, 2, 'zhCN', '把旗子给我！', ''),
  (7725, 0, 'zhCN', '奥图里斯派我过来的。他说你能帮我。', 'NULL'),
  (7726, 0, 'zhCN', '连起来说伙计！赞加沼泽怎么了？', ''),
  (7727, 0, 'zhCN', '我没时间处理这个！守备长，发生什么事了？', ''),
  (7729, 0, 'zhCN', '我是萨萨拉比姆派来收债的。还钱，否则我就不客气了。', 'NULL'),
  (7730, 0, 'zhCN', '我是萨萨拉比姆派来收债的。还钱，否则我就不客气了。', 'NULL'),
  (7731, 0, 'zhCN', '他想要“金币”。再说一次……要么付钱要么纳命来……', 'NULL'),
  (7732, 0, 'zhCN', '我是萨萨拉比姆派来收债的。还钱，否则我就不客气了。', 'NULL'),
  (7735, 0, 'zhCN', '沙塔尔是谁？', ''),
  (7735, 1, 'zhCN', '沙塔斯不是一座德莱尼的城市嘛？为什么允许其他人在这儿？', ''),
  (7757, 0, 'zhCN', '你为什么要把这堆东西修起来？', ''),
  (7759, 0, 'zhCN', '你在这里做什么？', ''),
  (7760, 0, 'zhCN', '最近有什么新闻，顾问？', ''),
  (7762, 0, 'zhCN', '不过我还没听说这么可憎的事情，当我在这世界还不是完全体的时候，可恶的德莱尼就抓住我了。', ''),
  (7763, 0, 'zhCN', '职责是什么？', ''),
  (7764, 0, 'zhCN', '离开？为什么会选择离开？', ''),
  (7765, 0, 'zhCN', '怎么办？我已经尝试过很多方法了。我尽全力帮助我在纳格兰的人民。每次我接近加尔鲁什，他都对我不屑一顾。', ''),
  (7766, 0, 'zhCN', '你信吗？', ''),
  (7767, 0, 'zhCN', '你养育了这里所有的兽人，祖母？', ''),
  (7768, 0, 'zhCN', '你好，祖母。加尔鲁什告诉我说你有话要跟我讲。', ''),
  (7768, 1, 'zhCN', '加尔鲁什无可救药了，祖母。我在帮助玛格汉的时候就担心这件事情了，我认为加尔鲁什不适合做一个领导者。', ''),
  (7769, 0, 'zhCN', '我需要一包高爆炸弹。', ''),
  (7771, 0, 'zhCN', '列兵维克斯，我还需要一个伪装。', 'NULL'),
  (7772, 0, 'zhCN', '斥候奈弗蒂丝，我需要另一套伪装。', ''),
