  (7938, 0, 'zhCN', '我能在哪里飞行。', ''),
  (7938, 1, 'zhCN', '将我送往萨尔玛！', ''),
  (7939, 0, 'zhCN', '我能在哪里飞行。', ''),
  (7939, 1, 'zhCN', '送我去荣耀堡！', ''),
