  (7957, 0, 'zhCN', '你有什么可出售的？', ''),
  (7959, 0, 'zhCN', '我准备好去敦霍尔德城堡了。', ''),
  (7964, 0, 'zhCN', '你为什么不逃跑？', ''),
  (7967, 0, 'zhCN', '带我去深渊沙洲！', ''),
  (7967, 1, 'zhCN', '带我去深渊沙洲！', ''),
  (7967, 4, 'zhCN', '借我一只驭风者，我要去断脊者营地！', ''),
  (7967, 5, 'zhCN', '我在执行一项轰炸任务。我需要一只双足飞龙毁灭者！', ''),
  (7970, 0, 'zhCN', '我正在执行前线指挥官金斯顿下达的轰炸任务。我需要一头武装狮鹫！', 'NULL'),
  (7970, 1, 'zhCN', '送我去破碎岗哨！', 'NULL'),
  (7974, 0, 'zhCN', '我已经尽力了，祖母。谢谢你的忠告。', ''),
  (7976, 0, 'zhCN', '我即将返回艾泽拉斯，祖母。', ''),
  (7977, 0, 'zhCN', '这是我的酋长，祖母。人民——来自我的世界——的领导者……杜隆坦的儿子，您的孙子。', ''),
  (7978, 0, 'zhCN', '祖母，我从未感到荣耀。杜隆坦已经战死很久了，但是他的英勇事迹广为我的世界所知。兽人居住在名为杜隆塔尔——以您的儿子为名——的地方。并且……<你呼了几口气，想了一下接下来要告诉祖母的事情。>', ''),
  (7979, 0, 'zhCN', '祖母，你是杜隆坦的母亲？', ''),
  (7981, 0, 'zhCN', '我弄丢了大法师瓦格斯的法杖。', ''),
  (7982, 0, 'zhCN', '把旅店设为我的家。', ''),
  (7982, 1, 'zhCN', '我想要浏览你的货物。', ''),
  (7984, 0, 'zhCN', '继续读下去，只要你敢……', ''),
  (7985, 0, 'zhCN', '继续读下去，只要你敢……', ''),
  (7986, 0, 'zhCN', '继续读下去，只要你敢……', ''),
  (7987, 0, 'zhCN', '继续读下去，只要你敢……', ''),
  (7988, 0, 'zhCN', '继续读下去，只要你敢……', ''),
  (7989, 0, 'zhCN', '继续读下去，只要你敢……', ''),
  (7999, 0, 'zhCN', '格雷克，你想尝尝由拉克妮亚制造的新武器吗？', ''),
  (8001, 0, 'zhCN', '你这有什么好消化的东西吗？', ''),
  (8009, 0, 'zhCN', '继续说。我在听。', ''),
  (8010, 0, 'zhCN', '我明白了。', ''),
  (8011, 0, 'zhCN', '然后你是怎么做的？', ''),
  (8012, 0, 'zhCN', '当时发生什么？', ''),
  (8013, 0, 'zhCN', '我明白了。', ''),
  (8014, 0, 'zhCN', '我还有些别的事情想问你。', ''),
  (8021, 0, 'zhCN', '让我看看你都卖些什么。', ''),
  (8023, 0, 'zhCN', '<按随机按钮。>', ''),
  (8033, 0, 'zhCN', '艾泽基尔说他有某本书……', ''),
  (8036, 0, 'zhCN', '<启动紧急停机装置。>', ''),
  (8040, 0, 'zhCN', '乌提斯？', ''),
  (8041, 0, 'zhCN', '谁攻击了法力熔炉：杜隆？', ''),
  (8044, 0, 'zhCN', '<更多>', ''),
  (8046, 0, 'zhCN', '这些科技来自哪儿？', ''),
  (8057, 0, 'zhCN', '奶酪，嗯？也许是……上了年纪的奶酪？', ''),
  (8058, 0, 'zhCN', '我需要买些材料和毒药，女士。', ''),
  (8059, 0, 'zhCN', '我需要修理。', ''),
  (8060, 0, 'zhCN', '对极了！', ''),
  (8060, 1, 'zhCN', '不！', ''),
  (8062, 0, 'zhCN', '试图联络星界商人玛里德。', ''),
  (8063, 0, 'zhCN', '你都提供些什么？', ''),
  (8070, 0, 'zhCN', '你都卖些什么？', ''),
  (8071, 0, 'zhCN', '星界商人玛里德。我带着更多关于虚空龙的消息回来了，我想和你做个交易——为了挣笔外快。我会照顾好那个麻烦的暗夜精灵和她的人类朋友。', ''),
  (8072, 0, 'zhCN', '请将我带到主人的巢穴。', ''),
  (8079, 0, 'zhCN', '我想要加入战场。', ''),
  (8081, 0, 'zhCN', '魔导师卡尔琳达派我来问你关于阿兰里昂的秘密。他看到了谁？', ''),
  (8082, 0, 'zhCN', '我早就准备好了。', ''),
  (8084, 0, 'zhCN', '我想看看你的装备。', ''),
  (8085, 0, 'zhCN', '告诉我更多关于此地任务的事情。', ''),
  (8088, 0, 'zhCN', '萨艾特，我弄丢了星界坐标，请再给我一个！', ''),
  (8088, 1, 'zhCN', '我需要一个时空道标，萨艾特。', ''),
  (8090, 0, 'zhCN', '<继续听>', ''),
  (8095, 0, 'zhCN', '告诉我可以飞到哪里去。', 'NULL'),
  (8096, 0, 'zhCN', '送我去地狱岩床！', 'NULL'),
