  (8098, 0, 'zhCN', '我想买一只。', ''),
  (8100, 0, 'zhCN', '带我去破碎岗哨！', ''),
  (8103, 0, 'zhCN', '把旅店设为我的家。', ''),
  (8104, 0, 'zhCN', '我想要加入战场。', ''),
  (8105, 0, 'zhCN', '我想要加入战场。', ''),
  (8110, 0, 'zhCN', '教我圣光之路', ''),
