  (8111, 0, 'zhCN', '我想要乘地铁去那遥远的光明之路。', ''),
  (8111, 1, 'zhCN', '我想要重置天赋。', ''),
  (8111, 2, 'zhCN', '我想要知道双天赋系统。', ''),
  (8113, 0, 'zhCN', '<开始紧急关闭。>', ''),
  (8115, 0, 'zhCN', '<开始紧急关闭。>', ''),
  (8116, 0, 'zhCN', '<开始紧急关闭。>', ''),
  (8120, 0, 'zhCN', '复仇军是什么？', ''),
  (8121, 0, 'zhCN', '我想我弄明白了。我可以来提供帮助吗？复仇军和虚空生物同样在威胁我们的生存。', ''),
  (8122, 0, 'zhCN', '所以，你的动机是？', ''),
