  (9299, 3, 'zhCN', '我想从你那里购物。', ''),
  (9301, 0, 'zhCN', '快来，巴德。是时候和冰霜巨魔玩玩了！', ''),
  (9302, 0, 'zhCN', '别再担心了，牦牛人。部落会拯救并保护你和你的人民，但是首先你必须拿到《部落的血誓》来宣誓向酋长效忠。', ''),
  (9303, 0, 'zhCN', '为了部落！', ''),
  (9304, 0, 'zhCN', '重复我的话：“Lok tar ogar！胜利或死亡！这是我为部落留下的最后誓言。因为他们是部落最英勇最无畏的战士。我为大酋长献上自己的热血和勇气。我是酋长意志的执行者。我是酋长的武器。从生到死——为了部落！"', ''),
  (9305, 0, 'zhCN', '是的，坦卡。惩罚是指定给部落成员的权利。', ''),
  (9307, 0, 'zhCN', '我还有点其他的事要问你。', ''),
  (9335, 0, 'zhCN', '嗯……青蛙说你就是叛徒，我的“朋友”。', 'NULL'),
