INSERT INTO `gossip_menu_option_locale` (`MenuID`, `OptionID`, `Locale`, `OptionText`, `BoxText`) VALUES
  (9833, 0, 'zhCN', '训练我', ''),
  (9833, 1, 'zhCN', '我想要浏览你的货物。', ''),
  (9838, 0, 'zhCN', '我想要建立工会。', ''),
  (9838, 1, 'zhCN', '我如何完成工会表格？', ''),
  (9839, 0, 'zhCN', '库尔迪拉……听起来很奇怪，但是我依然会继续寻找孩子的灵魂。米斯希尔萨·阿奈尔……这名字对你有什么意义？', ''),
  (9841, 0, 'zhCN', '你还好吧？我这就带你回霜堡，希望你还能坚持下去。', ''),
  (9842, 0, 'zhCN', '抱歉，我也是刚刚才到达这里，这里发生了什么事？', ''),
  (9843, 0, 'zhCN', '你先呆在这里，我去附近寻求支援。', ''),
  (9848, 0, 'zhCN', '能修理下我的装备吗？', ''),
  (9852, 0, 'zhCN', '盖米尔，奥贾尔、纳瓦留斯和塞穆在什么地方？', ''),
  (9852, 1, 'zhCN', '盖米尔，我不知道该怎么做，我还没有骑过这么庞大的身体。', ''),
  (9852, 2, 'zhCN', '我准备好了，盖米尔。准备出发！', ''),
  (9853, 0, 'zhCN', '你明白我的意思吗？现在我们必须了解彼此。', ''),
  (9853, 1, 'zhCN', '你需要什么样的帮助？', ''),
  (9854, 1, 'zhCN', '我弄丢了布莱恩的通讯器。', ''),
  (9855, 0, 'zhCN', '我还有几个问题，盖米尔。', 'NULL'),
  (9856, 0, 'zhCN', '给我看看你卖什么。', ''),
  (9857, 0, 'zhCN', '我准备好了，让我把你弄出去。', ''),
  (9859, 0, 'zhCN', '我准备好了，准备离开这里吧！', ''),
  (9860, 0, 'zhCN', '我还有几个问题，盖米尔。', 'NULL'),
  (9864, 0, 'zhCN', '我想把宠物寄存在这儿。', ''),
  (9864, 1, 'zhCN', '我在找我丢失的小宠物。', ''),
  (9865, 0, 'zhCN', '姐妹们，就这么做吧！', ''),
  (9866, 2, 'zhCN', '把旅店设为我的家。', ''),
  (9866, 3, 'zhCN', '让我看看你的货物。', ''),
  (9868, 1, 'zhCN', '把旅店设为我的家。', ''),
  (9868, 2, 'zhCN', '让我看看你的货物。', ''),
  (9869, 0, 'zhCN', '我挑战你，血色渣滓！', ''),
  (9870, 0, 'zhCN', '我听说维库女人根本不能打斗。如果你想证明我错了的话，就来试试吧。', ''),
  (9871, 0, 'zhCN', '训练我', ''),
  (9873, 0, 'zhCN', '训练我', ''),
  (9873, 1, 'zhCN', '我可以看看你的史诗宝石图纸吗？', ''),
  (9874, 0, 'zhCN', '省去热身吧，姐妹……还是你惧怕面对和你个头一样大的人？', ''),
  (9875, 0, 'zhCN', '不好意思，但我在完成这些动作前真的不能被打扰。', ''),
  (9878, 0, 'zhCN', '我有个坏消息要告诉你奥努森：我不得不打断你的美梦了！', ''),
  (9879, 0, 'zhCN', '训练我', ''),
  (9879, 1, 'zhCN', '让我看看你的货物。', ''),
  (9880, 0, 'zhCN', '我发现奇怪的铠甲。你能告诉我有关它的事吗？', ''),
  (9891, 0, 'zhCN', '雷心国王派我来参加霜脉矮人的试炼。我已经准备好了，弗亚林。', ''),
  (9891, 1, 'zhCN', '我要参加对抗巨龙的战斗。能给我一只雄鹰吗，弗亚林？', 'NULL'),
  (9892, 0, 'zhCN', '训练我', ''),
  (9893, 0, 'zhCN', '训练我', ''),
  (9894, 0, 'zhCN', '训练我', ''),
  (9895, 0, 'zhCN', '训练我', ''),
  (9899, 0, 'zhCN', '我准备好去寻找科洛米尔了。', ''),
  (9900, 0, 'zhCN', '尊敬的约库姆国王，如果您方便的话，能否告知我科洛米尔现在怎么样了？', ''),
  (9904, 0, 'zhCN', '我想建造一辆攻城坦克。', ''),
  (9904, 1, 'zhCN', '我想建造一辆投石车。', ''),
  (9904, 2, 'zhCN', '我想建造一辆弩车。', ''),
  (9906, 0, 'zhCN', '很抱歉打扰到你，酋长。但是，你的兄弟的灵魂可能遇到了危险。你能把关于他的回忆告诉我吗？', 'NULL'),
  (9906, 1, 'zhCN', '告诉我更多你的记忆。', ''),
  (9907, 0, 'zhCN', '和我说说这个提议。', ''),
  (9908, 0, 'zhCN', '然后发生了什么？', ''),
  (9909, 0, 'zhCN', '你想要我参加海兹竞技场来结束战争？', ''),
  (9910, 0, 'zhCN', '很好，我会参加这个竞赛的。', ''),
  (9917, 0, 'zhCN', '我准备好去往风暴群山了。', ''),
  (9917, 1, 'zhCN', '我准备好进入风暴峭壁了。', 'NULL'),
